    print(ProtocolHandler.protocol_handlers())  # All handlers
    print(ProtocolHandler.protocol_handlers((3, 5)))  # Specific handler
    print(ProtocolHandler.protocol_handlers((4, 0)))  # Unsupported version

from functools import wraps
from neo4j import GraphDatabase

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        @wraps(func)
        def wrapper(session, *args, **kwargs):
            return session.write_transaction(lambda tx: func(tx, *args, **kwargs), metadata=metadata, timeout=timeout)
        return wrapper
    return decorator

# Example usage
if __name__ == "__main__":
    uri = "bolt://localhost:7687"
    user = "neo4j"
    password = "password"

    def count_people_tx(tx):
        result = tx.run("MATCH (a:Person) RETURN count(a) AS persons")
        record = result.single()
        return record["persons"]

    @unit_of_work(timeout=100)
    def count_people(session):
        return count_people_tx(session)

    with GraphDatabase.driver(uri, auth=(user, password)) as driver:
        with driver.session() as session:
            print(count_people(session))

