import functools
import threading

def cached(cache, key=hash, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    if lock is None:
        lock = threading.RLock()

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            cache_key = key(*args, **kwargs)
            with lock:
                if cache_key in cache:
                    return cache[cache_key]
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

import time
from functools import lru_cache, wraps

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = lru_cache(maxsize=maxsize, typed=typed)

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            if key in cache.cache_info().hits:
                result, timestamp = cache.cache_get(key)
                if timer() - timestamp < ttl:
                    return result
                else:
                    cache.cache_clear(key)
            result = func(*args, **kwargs)
            cache.cache_set(key, (result, timer()))
            return result

        wrapper.cache_clear = cache.cache_clear
        wrapper.cache_info = cache.cache_info
        return wrapper

    return decorator
import time
from functools import wraps
from collections import OrderedDict

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items()))) if not typed else (args, tuple(sorted(kwargs.items())), type(args), type(kwargs))
            if key in cache:
                result, timestamp = cache[key]
                if timer() - timestamp < ttl:
                    return result
                else:
                    del cache[key]
            result = func(*args, **kwargs)
            cache[key] = (result, timer())
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        def cache_clear():
            cache.clear()

        def cache_info():
            return (len(cache), maxsize, len(cache), len(cache))

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        return wrapper

    return decorator

from functools import lru_cache

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = lru_cache(maxsize=maxsize, typed=typed)
        def wrapper(*args, **kwargs):
            return cache(func, *args, **kwargs)
        return wrapper
    return decorator

