import functools
import threading

def cachedmethod(cache, key=hash, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(method):
        @functools.wraps(method)
        def wrapper(self, *args, **kwargs):
            if lock is not None:
                with lock:
                    return _cached_call(cache, key, method, self, args, kwargs)
            return _cached_call(cache, key, method, self, args, kwargs)
        return wrapper
    return decorator

def _cached_call(cache, key, method, self, args, kwargs):
    k = key(args) if callable(key) else key
    if k in cache:
        return cache[k]
    result = method(self, *args, **kwargs)
    cache[k] = result
    return result

# Example usage
if __name__ == "__main__":
    class Example:
        def __init__(self):
            self.cache = {}

        @cachedmethod(cache=lambda self: self.cache, lock=threading.Lock())
        def compute(self, x):
            print(f"Computing {x}...")
            return x * x

    example = Example()
    print(example.compute(10))  # Computes and caches the result
    print(example.compute(10))  # Retrieves result from cache

