from collections import defaultdict

def _legacy_mergeOrderings(orderings):
    graph = defaultdict(list)
    in_degree = defaultdict(int)

    for ordering in orderings:
        for i in range(len(ordering) - 1):
            u, v = ordering[i], ordering[i + 1]
            graph[u].append(v)
            in_degree[v] += 1

    queue = [node for node in set(graph) if in_degree[node] == 0]
    result = []

    while queue:
        if len(queue) > 1:
            raise ValueError("Multiple possible orderings, cannot merge uniquely")
        node = queue.pop(0)
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Add remaining nodes that have no incoming edges
    for node in set(graph) - set(result):
        if in_degree[node] == 0:
            result.append(node)

    return result

# Example usage
if __name__ == "__main__":
    print(_legacy_mergeOrderings([
        ['x', 'y', 'z'],
        ['q', 'z'],
        [1, 3, 5],
        ['z']
    ]))

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    from collections import OrderedDict

    def issubclass_tuple(cls, classinfo):
        return any(issubclass(cls, c) for c in classinfo)

    minimal_classes = []
    for cls in classes:
        if not any(issubclass_tuple(cls, minimal_classes)):
            minimal_classes.append(cls)
        else:
            minimal_classes = [c for c in minimal_classes if not issubclass_tuple(c, (cls,))]

    return list(OrderedDict.fromkeys(minimal_classes))

