import csv
from io import StringIO

class Graph:
    def __init__(self, points):
        self.points = points

    def to_csv(self, separator=",", header=None):
        output = StringIO()
        csv_writer = csv.writer(output, delimiter=separator)

        if header is not None:
            csv_writer.writerow([header])

        for point in self.points:
            # Assuming point is a tuple of (coordinates, values)
            coordinates, values = point
            row = list(map(str, coordinates)) + list(map(str, values))
            csv_writer.writerow(row)

        return output.getvalue()

# Example usage
if __name__ == "__main__":
    graph = Graph(points=[((1, 2), (3, 4)), ((5, 6), (7, 8))])
    csv_data = graph.to_csv(separator=";", header="X,Y;A,B")
    print(csv_data)

