import copy

def difference(d1, d2, level=-1):
    def _difference(d1, d2, current_level):
        if current_level == 0:
            return {}

        result = {}
        for key in d1:
            if key not in d2:
                result[key] = d1[key]
            elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
                sub_diff = _difference(d1[key], d2[key], current_level - 1)
                if sub_diff:
                    result[key] = sub_diff
            elif d1[key] != d2[key]:
                result[key] = d1[key]
        return result

    return _difference(d1, d2, level if level != -1 else float('inf'))

