import re
from typing import Dict, List, Union

class ValidationError(Exception):
    def __init__(self, messages: List[Dict[str, str]]):
        self.messages = messages
        super().__init__(f"Validation errors: {self.messages}")

def _validate_labels(labels: Dict[Union[str, int, bool], Union[str, list, bool]]):
    key_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    errors = []

    for key, value in labels.items():
        key_str = str(key)
        value_str = str(value)

        if not isinstance(key, (str, int, bool)):
            errors.append({key_str: 'expected string, int, or bool as key'})
        elif not key_regex.match(key_str):
            errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9_]+$'"})

        if not isinstance(value, (str, int, bool)):
            errors.append({value_str: 'expected string, int, or bool as value'})
        elif not value_regex.match(value_str):
            errors.append({value_str: f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9_]+$'"})


    if errors:
        raise ValidationError(errors)

# Example usage
if __name__ == "__main__":
    labels = {
        "key1": "valid",
        "key2": ["invalid"],
        "$$": "invalid",
        True: True,
    }
    try:
        _validate_labels(labels)
    except ValidationError as err:
        print(err.messages)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    identifying_fields = {'apiVersion', 'kind', 'metadata'}
    observer_schema = {}

    for key, value in manifest_dict.items():
        if first_level and key in identifying_fields:
            observer_schema[key] = value
        elif isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
        else:
            observer_schema[key] = None

    return observer_schema

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    for obs_schema, resp_item in zip(observer_schema, response):
        if isinstance(obs_schema, dict) and isinstance(resp_item, dict):
            for key, value in obs_schema.items():
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], value, resp_item.get(key, {})
                )
        elif isinstance(obs_schema, list) and isinstance(resp_item, list):
            if not last_applied_manifest:
                last_applied_manifest.extend([{} for _ in obs_schema])
            for i, (schema_item, resp_sub_item) in enumerate(zip(obs_schema, resp_item)):
                if i >= len(last_applied_manifest):
                    last_applied_manifest.append({})
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[i], schema_item, resp_sub_item
                )

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for key, value in observer_schema.items():
        if key not in last_applied_manifest:
            last_applied_manifest[key] = response.get(key, None)
        if isinstance(value, dict) and isinstance(last_applied_manifest[key], dict):
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], value, response.get(key, {})
            )
        elif isinstance(value, list) and isinstance(last_applied_manifest[key], list):
            if not last_applied_manifest[key]:
                last_applied_manifest[key].extend([{} for _ in value])
            for i, (schema_item, resp_sub_item) in enumerate(zip(value, response.get(key, []))):
                if i >= len(last_applied_manifest[key]):
                    last_applied_manifest[key].append({})
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key][i], schema_item, resp_sub_item
                )

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for field, schema in observer_schema.items():
        if field in response:
            if isinstance(schema, dict) and isinstance(response[field], dict):
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], schema, response[field]
                )
            else:
                last_applied_manifest[field] = response[field]
        else:
