from typing import AnyStr, Union, Iterable, Dict, Sequence, List, Tuple
import re

class SQLParams:
    in_style = 'named'  # or 'ordinal'

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if SQLParams.in_style == 'named':
        pattern = re.compile(r':([a-zA-Z_][a-zA-Z0-9_]*)')
        out_style = '?'
        def convert_params(params):
            return list(params.values())
    elif SQLParams.in_style == 'ordinal':
        pattern = re.compile(r'\?')
        out_style = '?'
        def convert_params(params):
            return list(params)
    else:
        raise ValueError("Unsupported in-style parameter")

    formatted_sql = pattern.sub(out_style, sql)
    converted_params = [convert_params(params) for params in many_params]
    return formatted_sql, converted_params

import os
import json
import hashlib

class OCFLValidator:
    def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        if not os.path.exists(path) or not os.path.isdir(path):
            return False

        try:
            with open(os.path.join(path, 'ocfl_object_1.0'), 'r') as f:
                if f.read().strip() != 'ocfl_object_1.0':
                    return False
        except FileNotFoundError:
            return False

        try:
            with open(os.path.join(path, 'inventory.json'), 'r') as f:
                inventory = json.load(f)
        except (FileNotFoundError, json.JSONDecodeError):
            return False

        if not self._validate_inventory(inventory):
            return False

        for version in inventory.get('versions', {}).values():
            if not self._validate_version(path, version):
                return False

        return True

    def _validate_inventory(self, inventory):
        required_keys = {'id', 'type', 'digestAlgorithm', 'head', 'versions'}
        if not required_keys.issubset(inventory.keys()):
            return False

        if inventory['type'] != 'ocfl_object':
            return False

        return True

    def _validate_version(self, path, version):
        version_path = os.path.join(path, version['state']['name'])
        if not os.path.exists(version_path) or not os.path.isdir(version_path):
            return False

        for file_path, file_info in version['state']['contents'].items():
            full_path = os.path.join(version_path, file_path)
            if not os.path.exists(full_path):
                return False

            if not self._validate_file_hash(full_path, file_info['digest']):
                return False

        return True

    def _validate_file_hash(self, file_path, expected_hash):
        digest_algorithm, expected_value = expected_hash.split(':')
        hash_function = hashlib.new(digest_algorithm)
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_function.update(chunk)
        return hash_function.hexdigest() == expected_value

