import hashlib

class DigestChecker:
    def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Assuming manifest_files is a list of file paths and digests_used is a set of digests
        present_digests = set()

        for file_path in manifest_files:
            with open(file_path, 'rb') as file:
                file_content = file.read()
                file_digest = hashlib.sha256(file_content).hexdigest()
                present_digests.add(file_digest)

        # Check if all digests used are present
        return digests_used.issubset(present_digests)

