class PrettyPrintable:
    def __init__(self, data):
        self.data = data

    def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        indent_str = ' ' * indent
        if isinstance(self.data, dict):
            result = "{\n"
            for key, value in self.data.items():
                result += f"{indent_str}  {key}: {PrettyPrintable(value).pretty(indent + 2, debug)},\n"
            result += f"{indent_str}}"
            return result
        elif isinstance(self.data, list):
            result = "[\n"
            for item in self.data:
                result += f"{indent_str}  {PrettyPrintable(item).pretty(indent + 2, debug)},\n"
            result += f"{indent_str}]"
            return result
        else:
            return f"{indent_str}{repr(self.data)}"

