class StorageValidator:
    def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        def check_file(file_path):
            nonlocal good_objects
            if validate_objects:
                if not os.path.isfile(file_path):
                    if show_warnings:
                        print(f"Warning: {file_path} is not a valid file.")
                    return False
                if check_digests:
                    try:
                        with open(file_path, 'rb') as f:
                            file_hash = hashlib.sha256(f.read()).hexdigest()
                        # Here you would compare file_hash with the expected hash
                        # For demonstration, we assume all files are valid
                        good_objects += 1
                    except Exception as e:
                        if show_warnings:
                            print(f"Warning: Could not read {file_path}. Error: {e}")
                        return False
                else:
                    good_objects += 1
            return True

        def traverse_directory(directory):
            nonlocal num_objects
            for root, dirs, files in os.walk(directory):
                for name in files:
                    file_path = os.path.join(root, name)
                    num_objects += 1
                    check_file(file_path)

        # Assuming the storage root is the current directory for demonstration
        traverse_directory('.')

        return num_objects, good_objects

