import hashlib

class VersionValidator:
    def validate_version_inventories(self, version_dirs):
        root_inventory = self.load_inventory(os.path.join(version_dirs[0], 'inventory.txt'))
        content_digests = {}

        for version_dir in version_dirs:
            inventory_path = os.path.join(version_dir, 'inventory.txt')
            if not os.path.exists(inventory_path):
                raise FileNotFoundError(f"Inventory file not found for version {version_dir}")

            current_inventory = self.load_inventory(inventory_path)
            self.validate_inventory(current_inventory, root_inventory, version_dir)

            for item, digest in current_inventory.items():
                if item not in content_digests:
                    content_digests[item] = digest
                elif content_digests[item] != digest:
                    print(f"Content digest mismatch for {item} in version {version_dir}")

    def load_inventory(self, inventory_path):
        inventory = {}
        with open(inventory_path, 'r') as file:
            for line in file:
                item, digest = line.strip().split()
                inventory[item] = digest
        return inventory

    def validate_inventory(self, current_inventory, root_inventory, version_dir):
        for item in root_inventory:
            if item not in current_inventory:
                raise ValueError(f"Item {item} missing in inventory for version {version_dir}")

    def calculate_digest(self, file_path):
        hash_sha256 = hashlib.sha256()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_sha256.update(chunk)
        return hash_sha256.hexdigest()

