def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_values(value1, value2):
        if isinstance(value1, MappingNode) and isinstance(value2, MappingNode):
            merged_value = defaultdict(list)
            for k, v in value1.value:
                merged_value[k].append(v)
            for k, v in value2.value:
                merged_value[k].append(v)
            return MappingNode(tag='tag:yaml.org,2002:map', value=[
                (k, merge_values(v1, v2) if len(values) > 1 else values[0])
                for k, values in merged_value.items()
                for v1, v2 in zip(values, values[1:])
            ])
        else:
            return value2

    merged_dict = defaultdict(list)
    for key, value in nodes:
        merged_dict[key].append(value)

    result = []
    for key, values in merged_dict.items():
        merged_value = values[0]
        for value in values[1:]:
            merged_value = merge_values(merged_value, value)
        result.append((key, merged_value))

    return result

