class LenaValueError(Exception):
    pass

class Histogram:
    def __init__(self):
        self._scale = None
        self._data = []

    def fill(self, value):
        self._data.append(value)
        self._scale = None  # Invalidate scale when histogram is filled

    def scale(self, other=None, recompute=False):
        if other is None:
            if self._scale is None or recompute:
                self._scale = sum(self._data)
            return self._scale
        else:
            if self._scale is None:
                self._scale = sum(self._data)
            if self._scale == 0:
                raise LenaValueError("Histogram with scale equal to zero can't be rescaled.")
            factor = other / self._scale
            self._data = [x * factor for x in self._data]
            self._scale = other
            return self._scale

# Example usage
