from zope.interface import Interface, implementer, providedBy, Invalid
from inspect import signature, Parameter

class _VerifyError(Exception):
    def __init__(self, errors):
        self.errors = errors

    def __str__(self):
        return "\n".join(self.errors)

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set(attr for attr in iface.names() if callable(getattr(iface, attr)))
    required_attributes = set(attr for attr in iface.names() if not callable(getattr(iface, attr)))

    candidate_methods = set(attr for attr in dir(candidate) if callable(getattr(candidate, attr)))
    candidate_attributes = set(attr for attr in dir(candidate) if not callable(getattr(candidate, attr)))

    missing_methods = required_methods - candidate_methods
    missing_attributes = required_attributes - candidate_attributes

    for method in missing_methods:
        errors.append(f"Missing method: {method}")

    for attribute in missing_attributes:
        errors.append(f"Missing attribute: {attribute}")

    for method in required_methods.intersection(candidate_methods):
        iface_method = getattr(iface, method)
        candidate_method = getattr(candidate, method)
        try:
            iface_sig = signature(iface_method)
            candidate_sig = signature(candidate_method)
            if not _signatures_match(iface_sig, candidate_sig):
                errors.append(f"Method {method} has incorrect signature")
        except ValueError as e:
            errors.append(f"Error checking signature for method {method}: {e}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise _VerifyError(errors)

    return True

def _signatures_match(iface_sig, candidate_sig):
    iface_params = iface_sig.parameters
    candidate_params = candidate_sig.parameters

    if len(iface_params) != len(candidate_params):
        return False

    for iface_name, iface_param in iface_params.items():
        candidate_param = candidate_params.get(iface_name)
        if candidate_param is None:
            return False
        if iface_param.annotation != candidate_param.annotation:
            return False
        if iface_param.default != candidate_param.default:
            return False
        if iface_param.kind != candidate_param.kind:
            return False

    return True

from zope.interface import Interface, implementer, providedBy, Invalid
from inspect import signature, Parameter

class IExample(Interface):
    def method1(arg1, arg2):
        """Method 1"""

    def method2(arg1):
        """Method 2"""

    attr1 = Attribute("Attribute 1")

@implementer(IExample)
class Candidate:
    def method1(self, arg1, arg2):
        pass

    def method2(self, arg1):
        pass

    attr1 = 42

def verifyObject(iface, candidate, tentative=False):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide the interface {iface}")

    for name, method in iface.namesAndDescriptions():
        if isinstance(method, Interface.Method):
            if not hasattr(candidate, name):
                errors.append(f"Missing method: {name}")
            else:
                candidate_method = getattr(candidate, name)
                if not callable(candidate_method):
                    errors.append(f"Not callable: {name}")
                else:
                    try:
                        sig = signature(candidate_method)
                        iface_sig = signature(method)
                        if not sig.parameters.items() >= iface_sig.parameters.items():
                            errors.append(f"Incorrect signature for {name}: expected {iface_sig}, got {sig}")
                    except ValueError as e:
                        errors.append(f"Signature error for {name}: {e}")

        elif isinstance(method, Interface.Attribute):
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute: {name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

# Example usage
try:
