    print("Candidate verifies successfully.")
except Invalid as e:
    print(f"Verification failed: {e}")

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        if tentative:
            return all(hasattr(candidate, attr) for attr in dir(iface) if not attr.startswith('__'))
        else:
            return all(isinstance(getattr(candidate, attr), type(getattr(iface, attr))) for attr in dir(iface) if not attr.startswith('__'))
    except AttributeError:
        return False

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metas = set(type(base) for base in bases)
    if not metas:
        return type
    elif len(metas) == 1:
        return metas.pop()
    else:
        raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

