        del self._dict[key]

    def __len__(self):
        return len(self._dict)

    def popitem(self):
        """Remove and return a random `(key, value)` pair."""
        if not self._dict:
            raise KeyError("popitem(): dictionary is empty")
        key = random.choice(list(self._dict.keys()))
        value = self._dict.pop(key)
