from typing import Optional

class RequestType:
    def __init__(self, public_message: Optional[str] = None, private_message: Optional[str] = None, legacy_payload: Optional[bool] = False):
        self.public_message = public_message
        self.private_message = private_message
        self.legacy_payload = legacy_payload

def identify_request(request: RequestType) -> str:
    if request.public_message:
        return "Diaspora public message request"
    elif request.private_message:
        return "Diaspora private message request"
    elif request.legacy_payload:
        return "Diaspora legacy payload request"
    else:
        return "Unknown request type"

