def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Assuming a tag can only contain alphanumeric characters and underscores, and must start with a letter
    return bool(re.match(r'^[A-Za-z][A-Za-z0-9_]*$', tag))

import json
from xml.etree import ElementTree as ET
from typing import Dict, Any

def parse_diaspora_webfinger(document: str) -> Dict[str, Any]:
    try:
        # Try to parse as JSON
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            root = ET.fromstring(document)
            if root.tag != '{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD':
                raise ValueError("Invalid XRD document")

            result = {}
            for element in root:
                tag = element.tag.split('}')[-1]
                if tag == 'Subject':
                    result['subject'] = element.text
                elif tag == 'Alias':
                    result.setdefault('aliases', []).append(element.text)
                elif tag == 'Link':
                    link = {}
                    for attr, value in element.attrib.items():
                        link[attr] = value
                    result.setdefault('links', []).append(link)
            return result
        except ET.ParseError:
            raise ValueError("Document is neither valid JSON nor XRD")

