import yaml

class IRValidatorException(Exception):
    pass

class SpecValidator:
    REQUIRED_FIELDS = {'name', 'version', 'description'}

    @classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("Spec content is None")

        try:
            spec_data = yaml.safe_load(spec_content)
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Error parsing YAML: {e}")

        if not isinstance(spec_data, dict):
            raise IRValidatorException("Spec content is not a valid YAML dictionary")

        missing_fields = cls.REQUIRED_FIELDS - spec_data.keys()
        if missing_fields:
            raise IRValidatorException(f"Missing required fields: {missing_fields}")

        return spec_data

import yaml
from pathlib import Path

class IRValidatorException(Exception):
    pass

class Validator:
    REQUIRED_FIELDS = {'field1', 'field2', 'field3'}  # Example required fields

    @classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("No YAML file provided")

        file_path = Path(yaml_file)
        if not file_path.exists():
            raise IRValidatorException(f"File {yaml_file} does not exist")

        with file_path.open('r') as file:
            data = yaml.safe_load(file)

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a dictionary")

        missing_fields = cls.REQUIRED_FIELDS - data.keys()
        if missing_fields:
            raise IRValidatorException(f"Missing required fields: {missing_fields}")

        return data

