    print(updated_spec_dict)

class SpecResolver:
    def __init__(self, spec):
        self.spec = spec

    def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources."""
        defaults = {}
        for arg, details in self.spec.items():
            if 'default' in details:
                defaults[arg] = details['default']
        return defaults

