import re

class ArgumentSplitter:
    def get_nested_custom_and_control_args(self, args):
        control_args = {}
        nested_args = {}
        custom_args = {}

        for arg in args:
            if arg.startswith('--control_'):
                key, value = self._split_arg(arg)
                control_args[key] = value
            elif arg.startswith('--custom_'):
                key, value = self._split_arg(arg)
                custom_args[key] = value
            else:
                key, value = self._split_arg(arg)
                nested_args[key] = value

        return control_args, nested_args

    def _split_arg(self, arg):
        match = re.match(r'--([^=]+)=(.*)', arg)
        if match:
            return match.group(1), match.group(2)
        return arg, None

# Example usage
if __name__ == "__main__":
    splitter = ArgumentSplitter()
    args = [
        '--control_arg1=value1',
        '--nested_arg1=value2',
        '--custom_arg1=value3',
        '--another_nested_arg=value4'
    ]
    control_args, nested_args = splitter.get_nested_custom_and_control_args(args)
    print("Control Args:", control_args)
    print("Nested Args:", nested_args)

import ast

class VarMerger:
    @staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if extra_vars is None:
            extra_vars = []

        for extra_var in extra_vars:
            try:
                # Assuming extra_var is a string in the format "key=value"
                key, value = extra_var.split('=', 1)
                # Attempt to evaluate the value as a Python literal
                vars_dict[key] = ast.literal_eval(value)
            except (ValueError, SyntaxError):
                # If evaluation fails, treat the value as a string
                vars_dict[key] = value

        return vars_dict

# Example usage
if __name__ == "__main__":
    vars_dict = {'a': 1, 'b': 2}
    extra_vars = ['c=3', 'd="hello"', 'e=[1, 2, 3]']
    merged_vars = VarMerger.merge_extra_vars(vars_dict, extra_vars)
    print(merged_vars)

import os
import json

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
    if not os.path.exists(spec_path):
        raise FileNotFoundError(f"Plugin spec file not found at {spec_path}")

    with open(spec_path, 'r') as file:
        plugin_spec = json.load(file)

    return flatten_dict(plugin_spec)

